from mcp.server.mcpserver.exceptions import ResourceNotFoundError

@mcp.resource("tracker://issues/{issue_id}", mime_type="application/json")
def issue_resource(issue_id: str) -> str:
    """One issue in full, as JSON."""
    issue = find_issue(issue_id)
    if issue is None:
        raise ResourceNotFoundError(f"No issue {issue_id}")
    return json.dumps(issue)

import re
ISSUE_ID_RE = re.compile(r"HAR-\d{1,5}")

def check(raw):
    s = raw.strip().upper()
    return bool(ISSUE_ID_RE.fullmatch(s)), bool(ISSUE_ID_RE.match(s))

print(check(" har-12 "), check("HAR-12; rm -rf /"))

def leaks(args, private_values):
    blob = json.dumps(args).lower()
    return any(v.lower() in blob for v in private_values)

cfgs = {"A": (0.88, 0.04), "B": (0.91, 0.03), "C": (0.95, 0.09)}  # (success, $ per success)
def dominated(x):
    sx, cx = cfgs[x]
    return any(s >= sx and c <= cx and (s > sx or c < cx) for k, (s, c) in cfgs.items() if k != x)
print(sorted(k for k in cfgs if not dominated(k)))
